import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Πύλη κρατήσεων πελατών","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/customer-booking-gateway.md","filePath":"el/plus/customer-booking-gateway.md"}'),r={name:"el/plus/customer-booking-gateway.md"};function i(s,a,n,c,p,h){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="πυλη-κρατησεων-πελατων" tabindex="-1">Πύλη κρατήσεων πελατών <a class="header-anchor" href="#πυλη-κρατησεων-πελατων" aria-label="Permalink to &quot;Πύλη κρατήσεων πελατών&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="οριο-ενεργοποιησης" tabindex="-1">Όριο ενεργοποίησης <a class="header-anchor" href="#οριο-ενεργοποιησης" aria-label="Permalink to &quot;Όριο ενεργοποίησης&quot;">​</a></h2><p>Η ανεξάρτητη πύλη επισκεπτών διαθέτει ξεχωριστούς διακόπτες δημόσιου καταλόγου, προσφοράς, αιτήματος και αναζήτησης. Η δημόσια λήψη παραμένει απενεργοποιημένη μέχρι έγκριση. Η ιστοσελίδα δεν πρέπει να ενσωματώνει διαπιστευτήρια χειριστή ή να έχει απεριόριστη πρόσβαση στη βάση.</p><h2 id="εγκεκριμενη-ροη-πελατη" tabindex="-1">Εγκεκριμένη ροή πελάτη <a class="header-anchor" href="#εγκεκριμενη-ροη-πελατη" aria-label="Permalink to &quot;Εγκεκριμένη ροή πελάτη&quot;">​</a></h2><ol><li>Επιβεβαιώστε εγκεκριμένο κανάλι δημοσίευσης και κατάλογο εταιρείας. Εμφανίζονται μόνο δημοσιευμένες τοποθεσίες, υπηρεσίες και επιλογές οχημάτων.</li><li>Ο πελάτης επιλέγει διαδρομή, ημερομηνία/ώρα, επιβάτες, αποσκευές και υπηρεσία. Ελέγξτε υπηρεσία και χωρητικότητα. Ο διακομιστής επιστρέφει επαληθευμένο θετικό ναύλο ή απαίτηση χειροκίνητης προσφοράς· μην επινοείτε μηδενική τιμή.</li><li>Καταχωρίστε όνομα και τηλέφωνο επιβάτη· το email είναι προαιρετικό. Μην επινοείτε διεύθυνση email.</li><li>Ελέγξτε τρέχουσα προσφορά και υποβάλετε μία φορά μέσω εγκεκριμένης πύλης. Ο διακομιστής ελέγχει υπογεγραμμένο πλαίσιο προσφοράς και προστασίες διπλής/ταυτόχρονης υποβολής. Ληγμένη ή αλλαγμένη προσφορά απαιτεί νέο έλεγχο.</li><li>Ελέγξτε αναφορά και κατάσταση κράτησης. Αίτημα δεν ισοδυναμεί με πληρωμή ή άδεια αυτόματης ανάθεσης. Ο χειριστής ελέγχει εκκρεμείς προσφορές, αντιστοίχιση CRM και κράτηση πριν την επιβεβαίωση/ανάθεση.</li></ol><h2 id="αποδοχη-πριν-τη-δημοσιευση" tabindex="-1">Αποδοχή πριν τη δημοσίευση <a class="header-anchor" href="#αποδοχη-πριν-τη-δημοσιευση" aria-label="Permalink to &quot;Αποδοχή πριν τη δημοσίευση&quot;">​</a></h2><p>Ελέγξτε απομόνωση εταιρείας και καναλιού, περιορισμένη πρόσβαση βάσης, προστασία κατάχρησης, αλλοίωση προσφοράς, διπλές υποβολές, ασφαλή σύνδεση CRM, προαιρετικό email, ασφαλή αναζήτηση επιβάτη και συμπεριφορά απενεργοποιημένων λειτουργιών. Χρησιμοποιήστε απομονωμένα συνθετικά δεδομένα και ξεχωριστή έγκριση παρόχων. Μην δημοσιεύετε πριν από εγκεκριμένη αποδοχή και εμπορική ενεργοποίηση.</p><p>Δείτε <a href="/el/plus/create-reservation.html">Δημιουργία κράτησης</a>, <a href="/el/plus/passenger-information.html">Στοιχεία επιβάτη</a> και <a href="/el/integrations/third-party-api-setup.html">API τρίτων</a>.</p>',9)])])}const u=e(r,[["render",i]]);export{m as __pageData,u as default};
